			'es' => array( 'Excelente aplicación móvil', 'Reembolso semanal', 'Depósito mínimo bajo' ), 'pt' => array( 'Excelente aplicação móvel', 'Cashback semanal', 'Depósito mínimo baixo' ), 'fr' => array( 'Excellente application mobile', 'Cashback hebdomadaire', 'Dépôt minimum bas' ), 'it' => array( 'Ottima app mobile', 'Cashback settimanale', 'Deposito minimo basso' ), 'sv' => array( 'Utmärkt mobilapp', 'Veckovis cashback', 'Låg minimiinsättning' ), 'nb' => array( 'Utmerket mobilapp', 'Ukentlig cashback', 'Lavt minimumsinnskudd' ), 'fi' => array( 'Erinomainen mobiilisovellus', 'Viikoittainen cashback', 'Matala minimitalletus' ), 'nl' => array( 'Uitstekende mobiele app', 'Wekelijkse cashback', 'Lage minimumstorting' ), 'ja' => array( '優れたモバイルアプリ', '毎週のキャッシュバック', '低い最低入金額' ), 'pl' => array( 'Świetna aplikacja mobilna', 'Cotygodniowy cashback', 'Niski minimalny depozyt' ), 'cs' => array( 'Skvělá mobilní aplikace', 'Týdenní cashback', 'Nízký minimální vklad' ), 'ro' => array( 'Aplicație mobilă excelentă', 'Cashback săptămânal', 'Depozit minim redus' ), 'el' => array( 'Εξαιρετική εφαρμογή για κινητά', 'Εβδομαδιαίο cashback', 'Χαμηλή ελάχιστη κατάθεση' ),
