foreach ( $legal_pages as $key => $variants ) {
	$per_lang = array();
	foreach ( array( 'en', 'de', 'zh', 'es', 'pt', 'fr', 'it', 'sv', 'nb', 'fi', 'nl', 'ja', 'pl', 'cs', 'ro', 'el' ) as $lang ) {
		$v    = $variants[ $lang ];
		$slug = $legal_page_slug_overrides[ $key ][ $lang ] ?? sanitize_title( $v['title'] );
		$per_lang[ $lang ] = array(
			'args' => array(
				'post_type'    => 'page',
				'post_title'   => $v['title'],
				'post_content' => $v['content'],
				'post_status'  => 'publish',
				'post_name'    => $slug,
			),
		);
	}
	ww_seed_post_i18n( $per_lang );
}

